if (!function_exists('pipup_handle_intent') && defined('DIR_MODULES')) {
    include_once(DIR_MODULES . 'pipup/pipup.lib.php');
}
$text = '';
if (isset($phrase) && $phrase !== '') {
    $text = $phrase;
} elseif (isset($command) && $command !== '') {
    $text = $command;
} elseif (isset($details) && is_array($details) && isset($details['message'])) {
    $text = $details['message'];
}
$term = isset($terminal) ? $terminal : '';
$res = pipup_handle_intent($text, $term);
if (function_exists('sg')) {
    sg('pipupLastResult', $res['message']);
}
return $res;
